{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_floor_pendency1 AS ( SELECT \"WAREHOUSE\", status as reason, \"SAPL-WH1\" as inward_type, \"SAPL-WH2\" as source, store_returns::integer as quantity, SAPL_EMIZA as remark, \"SAPL-SR\" as dummy_1, TO_DATE(\"TOTAL\",\'DD/MM/YYYY\') as ageing_date FROM SNITCH_DB.MAPLEMONK.GS_FLOOR_PENDENCY ) ; CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_summary_wh AS WITH rts AS ( SELECT TRY_TO_DATE(entry_date, \'DD/MM/YYYY\') AS date, sku AS style, description, repeat, new_style, CAST(REPLACE(online_qty, \',\', \'\') AS INT) as online_qty, vendor, rts_status, TRY_TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') AS expected_delivery_date, warehouse, class, ars, remark, photoshoot_received, qc_status, qc_report, costing, logic_po, rfid_tags, collection, delhi, south, fabric_dc, work_order, mini_marker, invoice FROM snitch_db.maplemonk.gs_onlinegoods_rts ) SELECT rts.*, am.category, am.product_name, am.price, am.total_eoq, am.available_units, am.sku_class, am.sellable_inventory, am.status, md.final_status, case when logic_po is null and (lower(photoshoot_received) not in (\'yes\') or photoshoot_received is null) then \'Shoot + PO Pending\' when logic_po is null then \'PO Pending\' when lower(photoshoot_received) not in (\'yes\') or photoshoot_received is null then \'Shoot Pending\' else null end as RCA, case when rts.style like \'%MP%\' then \'MARKETPLACE\' when repeat = \'YES\' THEN \'REPEAT\' when md.final_status = \'INWARD_NOT_DONE\' then \'CATALOGUED\' when rts.style like \'%4MLX%\' then \'LUXE\' when lower(description) like \'%trouse%\' THEN \'BOTTOMS\' when lower(description) like \'%short%\' THEN \'BOTTOMS\' when lower(description) like \'%deni%\' THEN \'BOTTOMS\' when lower(description) like \'%py%\' THEN \'BOTTOMS\' when lower(description) like \'%jogg%\' THEN \'BOTTOMS\' when lower(description) like \'%chino%\' THEN \'BOTTOMS\' when lower(description) like \'%track%\' THEN \'BOTTOMS\' when lower(description) like \'%pant%\' THEN \'BOTTOMS\' when lower(description) like \'%cargo%\' THEN \'BOTTOMS\' when lower(description) in (\'trousers\',\'short\',\'boxer\',\'denim\',\'pyjama\',\'\') THEN \'BOTTOMS\' when lower(description) like \'%jac%\' THEN \'WINTER\' when lower(description) like \'%sweat%\' THEN \'WINTER\' end as PRIORITY FROM rts LEFT JOIN snitch_db.maplemonk.availability_master_v2 am ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN am.sku_group) > 0 AND LEFT(am.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(am.sku_group, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN am.sku_group) > 0 THEN UPPER(SPLIT_PART(am.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(am.sku_group, \'-\', 2)) || \'%\' ELSE UPPER(am.sku_group) || \'%\' END LEFT JOIN snitch_db.maplemonk.sku_group_sample_to_live md ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN md.sku_group) > 0 AND LEFT(md.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN md.sku_group) > 0 THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(md.sku_group, \'-\', 2)) || \'%\' ELSE UPPER(md.sku_group) || \'%\' END where md.final_status not in (\'NO_ISSUES\',\'others\') ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOW_QTY_BINS AS with data as ( select facility, \"Shelf Code\" as SHELF_CODE, zone, \"Section Code\" as SECTION_CODE, BIN_CATEGORY,ROW_NAME,RACK_NAME,SHELF_NAME,BIN_NAME, sum(total_qty) as TOTAL_QTY from snitch_db.maplemonk.inventory_bin_analysis where \"Section Code\" not in (\'DEF\') AND lower(\"Shelf Code\") not like \'%half%\' AND (\"Shelf Code\") not like \'%R1-%\' AND (\"Shelf Code\") not like \'%R2-%\' AND (\"Shelf Code\") not like \'%R3-%\' AND (\"Shelf Code\") not like \'%R4%\' AND (\"Shelf Code\") not like \'%R5%\' AND (\"Shelf Code\") not like \'%R6%\' AND (\"Shelf Code\") not like \'%R7%\' AND (\"Shelf Code\") not like \'%R8%\'AND (\"Shelf Code\") not like \'%R9%\' group by 1,2,3,4,5,6,7,8,9 ), analysis as ( select *, CASE WHEN TOTAL_QTY is null or total_qty = 0 then \'0\' WHEN TOTAL_QTY = 1 then \'1\' WHEN TOTAL_QTY = 2 then \'2\' WHEN TOTAL_QTY = 3 then \'3\' WHEN TOTAL_QTY = 4 then \'4\' WHEN TOTAL_QTY = 5 then \'5\' WHEN TOTAL_QTY >= 6 and TOTAL_QTY < 11 then \'6-10\' WHEN TOTAL_QTY >= 11 and TOTAL_QTY <= 15 then \'11-15\' WHEN TOTAL_QTY >= 16 and TOTAL_QTY <= 20 then \'16-20\' WHEN TOTAL_QTY >= 21 and TOTAL_QTY <= 25 then \'21-25\' WHEN TOTAL_QTY >= 26 and TOTAL_QTY <= 50 then \'26-50\' WHEN TOTAL_QTY >= 51 then \'51+\' ELSE NULL END AS BRACKET from data ) SELECT * FROM analysis ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            